function activeDifficulty(){return DIFFICULTY_ORDER[Math.min(journey.cleared,DIFFICULTY_ORDER.length-1)]}
let difficulty=activeDifficulty(),catalogGame='all',catalogKind='all',catalogRarity='all',catalogSearch='',catalogPage=0,returnOV='title',customDeck=[];
try{customDeck=JSON.parse(localStorage.getItem('lo_custom_deck')||'[]')}catch{}
if(!Array.isArray(customDeck))customDeck=[];else customDeck=customDeck.map(canonicalCardName);
function completeDifficulty(){
 const index=DIFFICULTY_ORDER.indexOf(difficulty);
 if(!G||G.tutorial||G.lv!==STG.length||G.wins<STG.length)return;
 identityCompleteCampaign();saveCampaignCarry();
 if(G.tierRecorded||index!==journey.cleared)return;
 G.tierRecorded=true;journey.cleared=Math.min(DIFFICULTY_ORDER.length,journey.cleared+1);journey.unlocked=Math.max(journey.unlocked||0,journey.cleared);
 storeJourney();
}
function journeyHTML(){
 const complete=journey.cleared===DIFFICULTY_ORDER.length;
 const note=complete?storyCopy('loop','notice'):(gameLanguage==='en'?`Current world: ${storyWorldName(activeDifficulty())}. Win all 16 encounters to reach the next door.`:`当前世界：${storyWorldName(activeDifficulty())}。赢过16位守路人，寻找下一扇门。`);
 return `<div class="journey-panel"><div class="journey-label">${gameLanguage==='en'?'Six worlds · 96 keepers':'六个世界 · 96位守路人'} · ${esc(storyCopy('loop','countLabel',{loop:(journey.loops||0)+1}))}</div><ol class="journey-steps" aria-label="旅途进度">${DIFFICULTY_ORDER.map((key,index)=>`<li class="${index<journey.cleared?'complete':key===activeDifficulty()?'current':'locked'}" ${index===journey.cleared?'aria-current="step"':''}><span class="journey-number">${index<journey.cleared?'✓':index+1}</span><b data-realm-short="${key}">${esc(storyWorldName(key))}</b><small>${index<journey.cleared?(gameLanguage==='en'?'Passed':'已走过'):key===activeDifficulty()?(gameLanguage==='en'?'Here':'身在此处'):(gameLanguage==='en'?'Ahead':'尚未抵达')}</small></li>`).join('')}</ol><p class="journey-description">${esc(note)}</p></div>`;
}
