 const result={deck:(carry?.deck||names).map(c=>typeof c==='string'?collectionCard(c):c).filter(Boolean).map(c=>makeCard(c)),reserve:(carry?.reserve||[]).map(c=>makeCard(c)),defeatedBosses:[...(carry?.defeatedBosses||[])]};
